macro_rules! tests {
    () => {
        # [cfg (test)] mod tests { # [test] # [cfg (unix)] fn parse_ceiling_dirs_from_environment_format () -> std :: io :: Result < () > { use std :: { fs , os :: unix :: fs :: symlink } ; use super :: * ; let dir = tempfile :: tempdir () . expect ("success creating temp dir") ; let direct_path = dir . path () . join ("direct") ; let symlink_path = dir . path () . join ("symlink") ; fs :: create_dir (& direct_path) ? ; symlink (& direct_path , & symlink_path) ? ; let symlink_str = symlink_path . to_str () . expect ("symlink path is valid utf8") ; let ceiling_dir_string = format ! ("{symlink_str}:relative::{symlink_str}") ; let ceiling_dirs = parse_ceiling_dirs (OsStr :: new (ceiling_dir_string . as_str ())) ; assert_eq ! (ceiling_dirs . len () , 2 , "Relative path is discarded") ; assert_eq ! (ceiling_dirs [0] , symlink_path . canonicalize () . expect ("symlink path exists") , "Symlinks are resolved") ; assert_eq ! (ceiling_dirs [1] , symlink_path , "Symlink are not resolved after empty item") ; dir . close () } # [test] # [cfg (windows)] fn parse_ceiling_dirs_from_environment_format () -> std :: io :: Result < () > { use std :: { fs , os :: windows :: fs :: symlink_dir } ; use super :: * ; let dir = tempfile :: tempdir () . expect ("success creating temp dir") ; let direct_path = dir . path () . join ("direct") ; let symlink_path = dir . path () . join ("symlink") ; fs :: create_dir (& direct_path) ? ; symlink_dir (& direct_path , & symlink_path) ? ; let symlink_str = symlink_path . to_str () . expect ("symlink path is valid utf8") ; let ceiling_dir_string = format ! ("{};relative;;{}" , symlink_str , symlink_str) ; let ceiling_dirs = parse_ceiling_dirs (OsStr :: new (ceiling_dir_string . as_str ())) ; assert_eq ! (ceiling_dirs . len () , 2 , "Relative path is discarded") ; assert_eq ! (ceiling_dirs [0] , direct_path , "Symlinks are resolved") ; assert_eq ! (ceiling_dirs [1] , symlink_path , "Symlink are not resolved after empty item") ; dir . close () } }
    };
}

tests!();